const body = $json.body || $json;
const requiredFields = ['id_pedido', 'tienda', 'fecha_pedido', 'items'];
const missing = requiredFields.filter(f => body[f] === undefined || body[f] === null || body[f] === '');
const itemsValid = Array.isArray(body.items) && body.items.length > 0;
return [{ json: { ...body, datos_completos: missing.length === 0 && itemsValid, campos_faltantes: missing.concat(itemsValid ? [] : ['items (vacio o invalido)']).join(', ') } }];

const payload = $('Code - Normalizar y Validar Payload').item.json;
const stockRecords = $input.all().map(r => r.json);
const insuficientes = [];
for (const item of payload.items) {
  const stockRec = stockRecords.find(s => {
    const skus = s.fields['SKU (from Producto)'] || [];
    return skus.some(sku => (sku || '').toLowerCase() === (item.sku || '').toLowerCase());
  });
  const disponible = stockRec ? (stockRec.fields['Cantidad Disponible'] || 0) : 0;
  if (disponible < item.cantidad) {
    insuficientes.push(`${item.producto || item.sku}: pide ${item.cantidad}, disponible ${disponible}`);
  }
}
return [{ json: { ...payload, stock_suficiente: insuficientes.length === 0, detalle_faltantes: insuficientes.join(' | ') } }];

