const raw = $json.content && $json.content[0] ? $json.content[0].text : '';
let parsed = null; let valido = false;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
  const keys = ['estado_pedido','fecha_estimada_entrega','mensaje_cliente'];
  valido = keys.every(k => parsed && parsed[k]);
} catch (e) { valido = false; }
return [{ json: { respuesta_ia_valida: valido, respuesta_ia: parsed, respuesta_ia_raw: raw } }];

